∀ {G : Type u_1} [inst : AddGroup G] {N : Type u_4} [inst_1 : AddGroup N] {H : AddSubgroup G} {K : AddSubgroup N}
  {J : AddSubgroup (G × N)},
  J ≤ H.prod K ↔ AddSubgroup.map (AddMonoidHom.fst G N) J ≤ H ∧ AddSubgroup.map (AddMonoidHom.snd G N) J ≤ K

∀ {G : Type u_1} [inst : AddGroup G] {N : Type u_4} [inst_1 : AddGroup N] {H : AddSubgroup G} {K : AddSubgroup N}
  {J : AddSubgroup (G × N)},
  H.prod K ≤ J ↔ AddSubgroup.map (AddMonoidHom.inl G N) H ≤ J ∧ AddSubgroup.map (AddMonoidHom.inr G N) K ≤ J

∀ {η : Type u_5} {f : η → Type u_6} [inst : (i : η) → AddGroup (f i)] {I : Set η} {H : (i : η) → AddSubgroup (f i)}
  {J : AddSubgroup ((i : η) → f i)},
  J ≤ AddSubgroup.pi I H ↔ ∀ i ∈ I, J ≤ AddSubgroup.comap (Pi.evalAddMonoidHom f i) (H i)

∀ {G : Type u_1} [inst : AddGroup G] {N : Type u_4} [inst_1 : AddGroup N] {G' : Type u_5} {N' : Type u_6}
  [inst_2 : AddGroup G'] [inst_3 : AddGroup N'] (f : G →+ N) (g : G' →+ N') (S : AddSubgroup N) (S' : AddSubgroup N'),
  AddSubgroup.comap (f.prodMap g) (S.prod S') = (AddSubgroup.comap f S).prod (AddSubgroup.comap g S')
